B.aHf={"\xe1":0,"\xe9":1,"\xed":2,"\xf3":3,"\xfa":4,"\xfc":5,"\xf1":6}
B.aEX=new A.bb(B.aHf,["a","e","i","o","u","u","n"],t.li)
B.aGI={Empuje:0,"Tir\xf3n":1,Pierna:2,"Cuerpo completo":3}
B.avM=s([B.bu,B.cw,B.bR],t.J_)
